   218	  private static applyFilters(session: TestSession, filters: TestSessionFilter[]): boolean {
   219	    const regexTest = (regex: string, value: string): boolean => {
   220	      try {
   221	        return new RegExp(regex).test(value);
   222	      } catch (e) {
   223	        return false;
   224	      }
   225	    };
   226	    // eslint-disable-next-line @typescript-eslint/no-shadow
   227	    const apply = (subject: string, filter: TestSessionFilter, inverted: boolean = false): boolean => {
   228	      if (filter.not && !inverted) return !apply(subject, filter, true);
   229	      if (Array.isArray(filter.value)) return filter.value.includes(subject);
   230	      const object = filter.subValue ? filter.subValue : filter.value;
   231	      switch (filter.type) {
   232	        case 'substring':
   233	          return subject.includes(object);
   234	        case 'equal':
   235	          return subject === object;
   236	        case 'regex':
   237	          return regexTest(object, subject);
   238	        default:
   239	          return false;
   240	      }
   241	    };
   242	    const filterOut: TestSessionFilter | undefined = filters
   243	      .find((nextFilter: TestSessionFilter): boolean => {
   244	        switch (nextFilter.target) {
   245	          case 'groupName':
   246	          case 'personLabel':
   247	          case 'mode':
   248	            return apply(session.data[nextFilter.target] || '', nextFilter);
   249	          case 'bookletId':
   250	            return apply(session.data.bookletName || '', nextFilter); // bookletId is clearer for XML-authors
   251	          case 'unitId':
   252	            return apply(session.data.unitName || '', nextFilter); // unitId is clearer for XML-authors
   253	          case 'unitLabel':
   254	            return apply(session.current?.unit?.label || '', nextFilter);
   255	          case 'bookletLabel':
   256	            return apply('metadata' in session.booklet ? session.booklet.metadata.label : '', nextFilter);
   257	          case 'blockId':
   258	            return apply(session.current?.ancestor?.blockId || '', nextFilter);
   259	          case 'blockLabel':
   260	            return apply(session.current?.ancestor?.label || '', nextFilter);
   261	          case 'testState': {
   262	            if (Array.isArray(nextFilter.value)) return false;
   263	            if (typeof session.data.testState[nextFilter.value] === 'undefined') return nextFilter.not;
   264	            return apply(session.data.testState[nextFilter.value], nextFilter);
   265	          }
   266	          case 'bookletStates': {
   267	            if (Array.isArray(nextFilter.value)) return false;
   268	            if (!session.bookletStates || typeof session.bookletStates[nextFilter.value] === 'undefined') return nextFilter.not;
   269	            return apply(session.bookletStates[nextFilter.value], nextFilter);
   270	          }
   271	          case 'state': {
   272	            return apply(session.state, nextFilter);
   273	          }
   274	          case 'bookletSpecies': {
   275	            return apply(session.booklet.species || '', nextFilter);
   276	          }
   277	          default:
   278	            return false;
   279	        }
   280	      });
   281	    return typeof filterOut !== 'undefined';
   282	  }
