   377	  sortSessions(sort: Sort, sessions: TestSession[]): TestSession[] {
   378	    return sessions
   379	      .sort((session1, session2) => {
   380	        const sortDirectionFactor = (sort.direction === 'asc' ? 1 : -1);
   381	        if (sort.active === 'timestamp') {
   382	          return (session1.data.timestamp - session2.data.timestamp) * sortDirectionFactor;
   383	        }
   384	        if (sort.active === '_checked') {
   385	          const session1isChecked = this.isChecked(session1);
   386	          const session2isChecked = this.isChecked(session2);
   387	          if (!session1isChecked && session2isChecked) {
   388	            return 1 * sortDirectionFactor;
   389	          }
   390	          if (session1isChecked && !session2isChecked) {
   391	            return -1 * sortDirectionFactor;
   392	          }
   393	          return 0;
   394	        }
   395	        if (sort.active === '_superState') {
   396	          return (TestSessionsSuperStates.indexOf(session1.state) -
   397	            TestSessionsSuperStates.indexOf(session2.state)) * sortDirectionFactor;
   398	        }
   399	        if (sort.active === '_currentBlock') {
   400	          const s1curBlock = session1.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
   401	          const s2curBlock = session2.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
   402	          return s1curBlock.localeCompare(s2curBlock) * sortDirectionFactor;
   403	        }
   404	        if (sort.active === '_currentUnit') {
   405	          const s1currentUnit = session1.current?.unit?.label ?? 'zzzzzzzzzz';
   406	          const s2currentUnit = session2.current?.unit?.label ?? 'zzzzzzzzzz';
   407	          return s1currentUnit.localeCompare(s2currentUnit) * sortDirectionFactor;
   408	        }
   409	        if (sort.active.startsWith('bookletState:')) {
   410	          const bookletState = sort.active.replace('bookletState:', '');
   411	          const a = session1.bookletStates && isBooklet(session1.booklet) ?
   412	            session1.booklet.states[bookletState].options[session1.bookletStates[bookletState]].label :
   413	            'zzzzzzzzzz';
   414	          const b = session2.bookletStates && isBooklet(session2.booklet) ?
   415	            session2.booklet.states[bookletState].options[session2.bookletStates[bookletState]].label :
   416	            'zzzzzzzzzz';
   417	          return a.localeCompare(b) * sortDirectionFactor;
   418	        }
   419	        let valA = session1.data[sort.active as keyof typeof session1.data] ?? 'zzzzzzzzzz';
   420	        let valB = session2.data[sort.active as keyof typeof session2.data] ?? 'zzzzzzzzzz';
   421	        if (typeof valA === 'number') {
   422	          valA = valA.toString(10);
   423	        }
   424	        if (typeof valB === 'number') {
   425	          valB = valB.toString(10);
   426	        }
   427	        if ((typeof valA === 'object') || (typeof valB === 'object')) {
   428	          return 0;
   429	        }
   430	        return valA.localeCompare(valB) * sortDirectionFactor;
   431	      });
   432	  }
