297	    this.subscriptions.push(this.messageService.showConfirmDialog({
298	      title: 'Testdurchführung beenden',
299	      content: 'Achtung! Diese Aktion sperrt und beendet sämtliche Tests dieser Sitzung.',
300	      confirmText: 'Ja, ich möchte die Testdurchführung beenden'
301	    }).pipe(
302	      take(1),
303	      filter((confirmed: boolean) => confirmed),
304	      tap(() => { this.isClosing = true; }),
305	      switchMap(() => this.tsm.commandFinishEverything()),
306	      delay(2000),
307	      takeUntil(this.routeChanged$),
308	      takeUntil(fromEvent(scope, 'abort')),
309	      finalize(() => { this.isClosing = false; })
310	    ).subscribe({
311	      next: () => { void this.router.navigateByUrl('/group-monitor'); },
312	      error: () => { this.messages.push({ level: 'error', customtext: '', text: 'Die Testdurchführung konnte nicht beendet werden.' }); }
