320	        customtext: 'gm_test_command_no_selected_block',
321	        text: 'Kein Zielblock ausgewählt'
322	      });
323	      return;
324	    }
325	
326	    (this.tsm.checked
327	      .some(testSession => isBooklet(testSession.booklet) &&
328	          this.currentlySelected?.element &&
329	          testSession.timeLeft &&
330	          (testSession.timeLeft[this.currentlySelected?.element?.id] <= 0)
331	      ) ?
332	      this.dialog.open(
333	        TimeRestrictionDialogComponent, {
334	          width: 'auto',
335	          data: <TimeRestrictionDialogData>{
336	            title:
